-- sql/23a-trello-enriquece-staging.sql
-- Cria staging _trello_enrich + popula 128 cards parseáveis.

DROP TABLE IF EXISTS _trello_enrich;

CREATE TABLE _trello_enrich (
  trello_id text PRIMARY KEY,
  comment_id text,
  valor numeric,
  forma text,
  data_pagamento date,
  descricao text
);

;

;

SELECT COUNT(*) AS cards_enrich_staging FROM _trello_enrich;